assignments.value:
={{ (() => {
  const body = $json.body;
  const MAX_RECORDS = 25, MAX_CHARS = 20000;
  const errors = {};
  let input = [];
  if (body && Array.isArray(body.records)) input = body.records;
  else if (body && typeof body === 'object' && !Array.isArray(body) && Object.keys(body).length) input = [body];

  if (input.length === 0) errors.records = 'Send {"records": [...]} with at least one record, or a single record object';
  if (input.length > MAX_RECORDS) errors.records = 'Max ' + MAX_RECORDS + ' records per request (got ' + input.length + ')';

  const batchId = 'BATCH-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + $execution.id;
  const records = [];
  input.slice(0, MAX_RECORDS).forEach((r, i) => {
    const at = 'records[' + i + ']';
    if (!r || typeof r !== 'object' || Array.isArray(r)) { errors[at] = 'Must be an object'; return; }
    const text = r.text ?? r.content ?? r.message ?? r.description;
    if (typeof text !== 'string' || !text.trim()) { errors[at + '.text'] = 'Required non-empty string (text | content | message | description)'; return; }
    if (text.length > MAX_CHARS) { errors[at + '.text'] = 'Max ' + MAX_CHARS + ' characters'; return; }
    records.push({
      record_id: String(r.id ?? (batchId + '-' + (i + 1))),
      batch_id: batchId,
      source: String(r.source ?? body.source ?? 'api'),
      author: String(r.author ?? r.email ?? r.name ?? ''),
      raw_text: text,
      received_at: $now.toISO()
    });
  });

  const valid = Object.keys(errors).length === 0;
  return { valid, errors, batch_id: batchId, count: records.length, records: valid ? records : [] };
})() }}

parameters.text:
=Analyze the record below and return the structured result.

Source: {{ $json.source }}
Author: {{ $json.author || 'unknown' }}

--- RECORD START ---
{{ $json.clean_text.slice(0, 6000) }}
--- RECORD END ---

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "maxLength": 300,
      "description": "Neutral 1-2 sentence summary in English"
    },
    "category": {
      "type": "string",
      "enum": [
        "sales_inquiry",
        "support_request",
        "complaint",
        "billing",
        "feedback",
        "partnership",
        "spam",
        "other"
      ]
    },
    "sentiment": {
      "type": "string",
      "enum": [
        "positive",
        "neutral",
        "negative"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high",
        "urgent"
      ]
    },
    "language": {
      "type": "string",
      "description": "ISO 639-1 code of the original text, e.g. en, id"
    },
    "keywords": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 5
    },
    "contains_pii": {
      "type": "boolean"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    }
  },
  "required": [
    "summary",
    "category",
    "sentiment",
    "priority",
    "language",
    "keywords",
    "contains_pii",
    "confidence"
  ],
  "additionalProperties": false
}

assignments.value:
={{ (() => {
  const t = $('On Workflow Error').first().json;
  const msg = t.execution?.error?.message ?? t.trigger?.error?.message ?? '';
  if (msg.includes('[CRITICAL]')) return 'CRITICAL';
  if (msg.includes('[WARNING]')) return 'WARNING';
  return 'ERROR';
})() }}
